//Checks if given string is a palindrome
// >>> is_palindrome("")
// true
// >>> is_palindrome("aba")
// true
// >>> is_palindrome("aaaaa")
// true
// >>> is_palindrome("zbcd")
// false
function is_palindrome(text){
  let start = 0;
  let end = text.length - 1;

  while (start < end) {
    if (text[start] !== text[end]) {
      return false;
    }
    start++;
    end--;
  }

  return true;
}

function is_Monotonic(A){
  let increasing = true;
  let decreasing = true;

  for(let i = 0; i < A.length - 1; i++){
    if(A[i] > A[i + 1]){
      increasing = false;
    }
    if(A[i] < A[i + 1]){
      decreasing = false;
    }
  }

  return increasing || decreasing;
}

