function find_combinations(test_list){
    const result = [];
    function backtrack(start, currentSum, currentCombination) {
        if (currentSum === 0) {
            result.push([...currentCombination]);
            return;
        }
        for (let i = start; i < test_list.length; i++) {
            if (test_list[i] <= currentSum) {
                currentCombination.push(test_list[i]);
                backtrack(i + 1, currentSum - test_list[i], currentCombination);
                currentCombination.pop();
            }
        }
    }
    backtrack(0, 0, []);
    return result;
}

