function all_Bits_Set_In_The_Given_Range(n, l, r){
    // Check if the range is valid
    if (l > r || l < 0 || r >= 32) {
        throw new Error("Invalid range");
    }

    // Create a mask with all bits set in the given range
    const mask = (1 << (r - l + 1)) - 1;

    // Shift the mask to the left by the number of bits to shift
    const shiftedMask = mask << l;

    // Perform the bitwise AND operation between the shifted mask and the given number
    const result = shiftedMask & n;

    // If the result is 0, all bits in the given range are set
    return result === 0;
}

