function shell_sort(my_list){
    let n = my_list.length;
    for (let gap = Math.floor(n / 2); gap > 0; gap = Math.floor(gap / 2)) {
        for (let i = gap; i < n; i++) {
            let temp = my_list[i];
            let j = i - gap;
            while (j >= 0 && my_list[j] > temp) {
                my_list[j + gap] = my_list[j];
                j -= gap;
            }
            my_list[j + gap] = temp;
        }
    }
    return my_list;
}

