function maxAverageOfPath(cost){
  const rows = cost.length;
  const cols = cost[0].length;

  // Initialize a 2D array to store the maximum average of paths ending at each cell
  const dp = Array.from({ length: rows }, () => Array(cols).fill(0));

  // Fill the dp array starting from the bottom-right corner
  for (let i = rows - 1; i >= 0; i--) {
    for (let j = cols - 1; j >= 0; j--) {
      if (i === rows - 1 && j === cols - 1) {
        dp[i][j] = cost[i][j];
      } else {
        const right = j + 1 < cols ? dp[i][j + 1] : 0;
        const down = i + 1 < rows ? dp[i + 1][j] : 0;
        dp[i][j] = cost[i][j] + Math.max(right, down);
      }
    }
  }

  // Find the maximum average of paths starting from the top-left corner
  let maxAverage = 0;
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      maxAverage = Math.max(maxAverage, dp[i][j]);
    }
  }

  return maxAverage / (rows * cols);
}

