  for (let i = 0; i < n; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j] && dp[j] + arr[i] > dp[i]) {
        dp[i] = dp[j] + arr[i];
      }
    }
  }

  // Calculate the maximum sum of decreasing subsequence
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      if (arr[i] > arr[j] && dp_desc[j] + arr[i] > dp_desc[i]) {
        dp_desc[i] = dp_desc[j] + arr[i];
      }
    }
  }

  // Find the maximum sum of bitonic subsequence
  let max_sum = 0;
  for (let i = 0; i < n; i++) {
    max_sum = Math.max(max_sum, dp[i] + dp_desc[i] - arr[i]);
  }

  return max_sum;
}

