function heap_queue_largest(nums, n) {
    // Helper function to perform heapify
    function heapify(arr, i, n) {
        let largest = i;
        let left = 2 * i + 1;
        let right = 2 * i + 2;

        if (left < n && arr[left] > arr[largest]) {
            largest = left;
        }

        if (right < n && arr[right] > arr[largest]) {
            largest = right;
        }

        if (largest !== i) {
            [arr[i], arr[largest]] = [arr[largest], arr[i]];
            heapify(arr, largest, n);
        }
    }

    // Helper function to build the heap
    function buildHeap(arr, n) {
        for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
            heapify(arr, i, n);
        }
    }

    // Main function to find the n largest integers
    function findNLargest(nums, n) {
        let size = nums.length;
        buildHeap(nums, size);

        let result = [];
        for (let i = size - 1; i >= size - n; i--) {
            result.push(nums[0]);
            [nums[0], nums[i]] = [nums[i], nums[0]];
            heapify(nums, 0, i);
        }

        return result;
    }

    return findNLargest(nums, n);
}

